-- Diary: Insert or Update
MERGE INTO Diary AS target
USING (VALUES ('61625950-9C26-46EF-1B98-08DD14BC2509', N'Sapper Arthur Carpenter''s 1918 WW1 diary chronicles his journey from England to East Africa, surviving submarine attacks in the Mediterranean, then months working as a stevedore along the coast. He witnessed the Armistice in November and finally sailed home in early 1919.', N'Sapper Arthur Carpenter', N'Local: WW1 Diary')) AS source (DiaryId, Description, Author, Title)
ON target.DiaryId = source.DiaryId
WHEN MATCHED THEN UPDATE SET Description = source.Description, Author = source.Author, Title = source.Title
WHEN NOT MATCHED THEN INSERT (DiaryId, Description, Author, Title) VALUES (source.DiaryId, source.Description, source.Author, source.Title);

-- DiaryEntry: Insert or Update
MERGE INTO DiaryEntry AS target
USING (VALUES
    ('B712F351-EFC2-4424-1A5C-08DE012FB313', '1918-05-21 07:20:00.0000000', N'Sandwich, UK', N'May 21st 1918, I left Sandwich for Southampton at 8.20 AM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('1E5128FE-F162-4D8B-1A5D-08DE012FB313', '1918-05-21 14:00:00.0000000', N'Southampton, UK', N'I arrived at Southampton at 3 PM and left Southampton at 8 PM on board the Antrim for France.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('03901FEA-BA5C-4EFF-1A5E-08DE012FB313', '1918-05-22 02:30:00.0000000', N'Le Harve, France', N'I arrived at Le Harve at 3.30 AM on May 22nd. We walked about four miles to a Rest Camp where we had our dinner or ''at least'' it was called a dinner. We had some white bread the first for years and it was lovely. I just managed to get a couple of bottles of beer which went down very good indeed.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('AF59B9C4-07CE-4EF8-1A5F-08DE012FB313', '1918-05-22 15:00:00.0000000', N'Le Harve, France', N'We left Le Harve at 4 PM by train for Marseilles Passing through a very pretty part of France and was stopped on the way at midnight on May 22nd by an air Raid on Paris.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C93F150D-47F6-4B53-1A60-08DE012FB313', '1918-05-23 10:00:00.0000000', N'Train, France', N'We had some biscuits and bully beef about 11 AM, the first food for 22 hours in fact all the time we were in the train we were fed once a day.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('6B2A8642-72A0-426A-1A61-08DE012FB313', '1918-05-23 23:00:00.0000000', N'Marseilles, France', N'We arrived at Marseilles at midnight on Friday May 24th and slept in the train for the rest of the night.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('FDC09682-3861-47A6-1A62-08DE012FB313', '1918-05-25 09:00:00.0000000', N'Rest Camp, Marseilles, France', N'Another Biscuit for Breakfast and fall in to march to the rest camp. About 2 miles we Reached the rest camp in the morning of May 25th very tired and thirsty.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('028371E0-2FA9-47BC-1A63-08DE012FB313', '1918-05-26 11:00:00.0000000', N'Rest Camp, Marseilles, France', N'Sunday May 26th me and my chum went for a walk by the sea front had 2 bottles of wine at 1/8 per large bottle, very good.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('8A081A04-0DC8-4189-1A64-08DE012FB313', '1918-05-27 11:00:00.0000000', N'Rest Camp, Marseilles, France', N'Monday May 27th cleaned up our camp and went for a walk along the sea front again. Very pretty place and very nice wine.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B4596A7E-9E8B-4207-4506-08DE0132BE20', '1918-05-28 11:00:00.0000000', N'Marseilles, France', N'Tuesday May 28th we had a day in Marseilles and had a good time. It is a very pretty city very fine buildings and very nice wine. Wine is very cheap here, but beer is 1 and 10 per pint bottle but very good. I met some boys from off a ship all from Southampton and had a lively hour with them, but we had to be back in camp by 8.30 PM which we were and quite sober after having a splendid time.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('1EB58DB9-9776-40F1-8923-08DE03520F77', '1918-05-29 11:00:00.0000000', N'Rest Camp, Marseilles, France', N'Wednesday May 29th had a nice quiet day in Camp and had sports and racing in the evening', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F9367DB8-B3E9-454C-8924-08DE03520F77', '1918-05-30 17:50:00.0000000', N'Rest Camp, Marseilles, France', N'Thursday May 30th nobody allowed to leave the Camp special parade at 6.50PM 14 men were absent so nobody allowed to leave the Camp next day.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('127DEA34-9440-4175-8925-08DE03520F77', '1918-05-31 16:00:00.0000000', N'Rest Camp, Marseilles, France', N'Friday May 31st had a splendid boxing competition in the evening and saw some good fighting by the black men. Nobody to leave the camp, under orders to pack up our bit to go away. Special parade at 5PM told we are leaving Rest Camp next day at 12.45 PM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('99DCF9E4-4B10-4125-8926-08DE03520F77', '1918-06-01 11:50:00.0000000', N'Rest Camp, Marseilles, France', N'June 1st up very early in the morning rolled our blankets ready for return to the stores. Left rest camp for docks at 12.50 PM. Put on Board SS Ormonde for work in the docks as there is a dockers strike on here.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('0570736A-9678-4670-8927-08DE03520F77', '1918-06-02 12:30:00.0000000', N'SS Ormonde, Marseilles, France', N'Sunday June 2nd told off for work as a steward to start work at 1.30PM had the morning off', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('573A6ABA-4D14-4F4A-8928-08DE03520F77', '1918-06-03 06:00:00.0000000', N'SS Ormonde, Marseilles, France', N'Monday June 3rd start work at 7AM until midday, afternoon off, evening in Marseilles. Had a good time', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('736DC7DC-5DA6-4732-8929-08DE03520F77', '1918-06-04 10:00:00.0000000', N'SS Ormonde, Marseilles, France', N'Tuesday June 4th started work at 8AM finished at 11AM took our bit ashore in the afternoon.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('7DA40CF7-D543-4669-892A-08DE03520F77', '1918-06-04 18:30:00.0000000', N'SS Indarra, Marseilles, France', N'Left the SS Ormonde at 6.30PM went on board the SS Indarra at 7.30PM. Very rough sleeping quarters, we slept on the floors and tables and on deck in fact anywhere. 32 men told off for table with room only for 16 men for meals. We have our meals in two sitting 16 each. Some hope we shall soon leave this ship we seem in for a rough time.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('8EA98653-EE86-4B46-892B-08DE03520F77', '1918-06-05 06:30:00.0000000', N'SS Indarra, Marseilles, France', N'Breakfast 7.30AM everybody complaining.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('456D2BC5-D7A1-441C-892C-08DE03520F77', '1918-06-05 13:00:00.0000000', N'SS Indarra, Marseilles, France', N'A lot of French troops come aboard this afternoon. Parade at 2PM with lifebelts for boat drill and inspection.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E350E787-8AE4-4723-892D-08DE03520F77', '1918-06-05 15:00:00.0000000', N'SS Indarra', N'June 5th left Marseilles at 4 PM, anchored just outside the harbour. For night I slept on deck under the stars and on the Mediterranean Sea on a lovely June night. A lot of fighting amongst the crew 2 fight on shore and 2 on board a very good start. One of the crews running about the deck with a damn great knife looking for trouble', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E0842D69-5DE2-429A-892E-08DE03520F77', '1918-06-06 22:15:00.0000000', N'SS Indarra', N'Thursday June 6th laid outside the harbour all day. Had boat drill and told off to our boat stations and left Marseilles for good or see. At 11.15 PM escorted by eight Japanese Destroyers we have five big troop ship in our convoy.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('1C496A7B-C20E-44C9-892F-08DE03520F77', '1918-06-07 11:00:00.0000000', N'SS Indarra', N'Friday June 7th started work and worked until dinner time then told off to work in steward''s department.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('10C5A10A-AAFD-42A0-8930-08DE03520F77', '1918-06-08 21:00:00.0000000', N'SS Indarra', N'June 8th I took charge of the officer''s bathroom to assist the bedroom steward I slept in the bathroom had a splendid bed, had all my food in first class pantry. I am still going on alright the sea is a bit choppy. Siren sounded 4 blasts at 10PM we all got the wind up thought old Fritzy had got us but it turned out to be a signal to the other boats.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('25C5F741-AA54-4271-8931-08DE03520F77', '1918-06-09 11:00:00.0000000', N'SS Indarra', N'Sunday June 9th sea very rough feeling a bit seasick but not very bad yet. We expect to reach Malta today.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('9E1F9389-BD13-4D89-8932-08DE03520F77', '1918-06-09 18:30:00.0000000', N'SS Indarra, Malta', N'Sunday we have arrived at Malta at 7.30PM after a fairly rough passage 10 Destroyers with us.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E086F129-D7D0-4883-8933-08DE03520F77', '1918-06-10 11:00:00.0000000', N'SS Indarra, Malta', N'Monday June 10th stayed in Malta harbour all day.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('72AC6233-9718-4DEE-8934-08DE03520F77', '1918-06-11 13:00:00.0000000', N'SS Indarra', N'Tuesday June 11th left Malta at 2.00 PM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('39124EC0-5741-4537-8935-08DE03520F77', '1918-06-12 05:00:00.0000000', N'SS Indarra', N'Wednesday June 12th sighted a submarine at 6.00 AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('34D9C72B-4573-45A2-8936-08DE03520F77', '1918-06-12 05:10:00.0000000', N'SS Indarra', N'Jap Destroyer sank her at 6.10 AM. We saw some sharks in the sea close to our boat the sea is very calm like a lake. We saw a big ship at night lighted up looks like a hospital ship, but a lot of our chaps has got the wind up and won''t go below but must sleep or walk about the decks with lifebelts on. I am still in the best of health. Order out that all port holes to be closed night and day and all watertight compartments closed. We are now in the most dangerous part, 2 big ships lost here last week. Not yet got the wind up.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D2483A0D-0298-48D0-8937-08DE03520F77', '1918-06-13 14:00:00.0000000', N'SS Indarra', N'Thursday June 13th an unlucky number, I hope it will be lucky this time. The sea is like a mill pond lovely and smooth we hope to reach Alexandria tomorrow, Friday, if all goes well everybody on board is very anxious and a lot of them has got the wind up. I changed into my thin drill clothes today feel a lot cooler and better. We were all inoculated again at 3PM that makes 3 times in less than 2 months.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('8BC915E7-F666-4652-8938-08DE03520F77', '1918-06-13 15:00:00.0000000', N'SS Indarra', N'It is 4PM now and the Japs have just opened fire on a submarine we cannot see the result from our ship. Jap signalled have sunk sub with depth charges.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('4F41D2C2-06A0-499E-8939-08DE03520F77', '1918-06-14 10:00:00.0000000', N'SS Indarra, Alexandria', N'Friday June 14th arrived safely at Alexandria at 11AM after a terrible exciting time a whole lot of German submarines just outside the harbour waiting for us we had a very big escort come out to meet us 2 seaplanes, 1 aeroplane, 1 balloon and about 20 war vessels of different kinds not including our own escort of 10 destroyers the Japs sank 3 subs in less than half an hour. We saw two blown right up out of the water. That made 5 submarines sunk on our Journey from Malta to Alexandria not so bad as they meant to have us but the Japs were too smart for them.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('8EFDCB1C-5266-4A47-893A-08DE03520F77', '1918-06-14 19:00:00.0000000', N'Alexandria', N'We left the SS Indarra at 8PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('83C60444-BEA3-4922-893B-08DE03520F77', '1918-06-14 20:00:00.0000000', N'Desert', N'and left Alexandria at 9PM. Traveling all night in the train through the desert where it was very hot in fact in the daytime you could not bear your hand to touch the side of the carriage.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('4CE49608-2EB8-4143-893C-08DE03520F77', '1918-06-15 10:00:00.0000000', N'Port Suez', N'We arrived at Port Suez at 11AM on June 15th.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B6736D74-14E4-4218-893D-08DE03520F77', '1918-06-15 14:30:00.0000000', N'SS Willochra', N'Went on board the SS Willochra and left Suez at 3.30PM. Passing though the Red Sea we saw the mountains on which Noah''s ark rested after the flood and mount Sinai where Moses wrote the 10 Commandments. These we saw on the Arabian coast on the other side the Egyptian coast we saw the monument marking the spot where children of Israel walked through the Red Sea.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('99803D96-2ED6-4AC3-1F79-08DE035E87B1', '1918-06-16 07:15:00.0000000', N'SS Willochra', N'Sunday June 16th I am told off for fatigue at 8.15AM this is not such a good ship as the SS Indarra was to us.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('414E1492-01E2-464A-1F7A-08DE035E87B1', '1918-06-18 11:00:00.0000000', N'SS Willochra', N'June 18th started work in the pantry. Plenty of good food and plenty of work.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('DDE798F3-0483-4DA4-1F7B-08DE035E87B1', '1918-06-20 09:30:00.0000000', N'SS Willochra', N'June 20th reached Aden 10.30, anchored outside harbour very hot here but a very nice breeze blowing. We were nearly five days passing through the Red Sea. We passed through Hells Gate', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('982A91C6-1CD6-4F16-1F7C-08DE035E87B1', '1918-06-20 13:00:00.0000000', N'SS Willochra', N'June 20th left Aden at 2PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A3C9B79E-DF29-475A-1F7D-08DE035E87B1', '1918-06-21 11:00:00.0000000', N'SS Willochra', N'June 21st In the Indian Ocean, very hot here not much breeze now seeing a lot of flying fish. The day very quiet nothing doing only the ocean to look upon. Wrote a letter home but missed the mail so must send it later on we passed Somaliland', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C9223B67-D9CB-4C84-1F7E-08DE035E87B1', '1918-06-22 20:00:00.0000000', N'SS Willochra', N'June 22nd saw the Southern Cross in the sky very clearly.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('9EB877C2-EEF1-487D-1F7F-08DE035E87B1', '1918-06-22 22:00:00.0000000', N'SS Willochra', N'Saturday June 22nd very strong wind blowing and the sea very rough most of our boys are seasick. Feeling a bit queer myself afraid I am in for a rough time this time', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F1CB6C89-D760-4125-1F80-08DE035E87B1', '1918-06-23 11:00:00.0000000', N'SS Willochra', N'Sunday June 23rd sea still very rough not got me down yet. Very near though but still at work. Both my mates sick. It is Sunday today I feel a bit down again always am on Sundays for I think of our Sunday in old England', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('540EE8F2-3394-4C1E-1F81-08DE035E87B1', '1918-06-24 11:00:00.0000000', N'SS Willochra', N'June 24th the sea is a bit more calm this morning. A quiet day crossed the line in the afternoon', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B2A36509-8EA7-4843-1F82-08DE035E87B1', '1918-06-25 11:00:00.0000000', N'SS Willochra', N'June 25th quiet day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('CBB9D02E-AFAE-4C06-1F83-08DE035E87B1', '1918-06-26 11:00:00.0000000', N'SS Willochra', N'June 26th quiet day sea much calmer. Concert in the evening turned out to be a good one.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('8913A597-6A93-4496-1F84-08DE035E87B1', '1918-06-27 02:00:00.0000000', N'SS Willochra, Mombasa, Kenya', N'June 27th Reached Mombasa 3AM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B84E2819-5B3E-4DCE-1F85-08DE035E87B1', '1918-06-27 06:00:00.0000000', N'SS Willochra, Kilindini, Mombasa, Kenya', N'Waited outside harbour entered into Kilindini at 7.0AM when the KAR (King''s African Rifles) disembarked on lighters as we could not get to the quayside.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('69540925-ED2D-439D-1F86-08DE035E87B1', '1918-06-27 15:30:00.0000000', N'SS Willochra, Mombasa, Kenya', N'We left Kilindini 4.30PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A14A63FB-1ACE-4654-1F87-08DE035E87B1', '1918-06-27 08:15:00.0000000', N'SS Willochra, Kilindini, Mombasa, Kenya', N'Hospital ship Gareon came into harbour at 9.15AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('CB56C299-8687-4B66-1F88-08DE035E87B1', '1918-06-28 09:30:00.0000000', N'SS Willochra, Dar es Salaam', N'June 28th arrived outside Dar es Salaam 10.30AM. Had to wait all day and night until 7AM for the tide before entering harbour.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F565033B-FF2F-4BE0-1F89-08DE035E87B1', '1918-06-28 16:30:00.0000000', N'SS Willochra, Dar es Salaam', N'British cruiser came alongside at 5.30PM and laid outside the Harbour.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('4F96943F-C86C-461A-1F8A-08DE035E87B1', '1918-06-29 05:15:00.0000000', N'SS Willochra, Dar es Salaam', N'June 29th Cruiser left at 6.15AM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('FF73BF7A-6D72-49C1-1F8B-08DE035E87B1', '1918-06-29 06:15:00.0000000', N'SS Willochra, Dar es Salaam', N'We entered Dar es Salaam harbour at 7.15 AM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('BBFD5E2F-44D1-45F1-1F8C-08DE035E87B1', '1918-06-29 09:00:00.0000000', N'SS Willochra, Dar es Salaam', N'Disembarked about 10AM. Marched to the JWT camp for a rest and to be reclassified for different stations along the coast', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('3E28FE19-FFA4-454B-26B5-08DE039E9AD3', '1918-07-03 16:30:00.0000000', N'SS Umtata, Dar es Salaam', N'July 3rd left camp to go on Board SS Umtata as cheeber with four other pals at 5.30PM to remain on board living and sleeping as second class passengers. Nice clean cabin 5 & 6 course breakfast coffee in bed at 6AM, luncheon at 1.30PM, afternoon tea at 4PM, late 6 or 7 Course dinner at 7PM. We are to stay on board for trips up and down the coast.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('4177F8DE-DFF9-4241-26B6-08DE039E9AD3', '1918-07-06 11:00:00.0000000', N'SS Umtata, Dar es Salaam', N'Saturday July 6th started to load in the evening', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('CD9F0B1A-E208-4EA0-26B7-08DE039E9AD3', '1918-07-09 10:00:00.0000000', N'SS Umtata, Dar es Salaam', N'Tuesday July 9th finished boarding and sailed for Zanzibar about 11AM arrived.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('8A07FBF4-A567-41EB-26B8-08DE039E9AD3', '1918-07-09 15:00:00.0000000', N'SS Umtata, Zanzibar', N'At Zanzibar 4PM July', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B4FA5B50-C9A7-43E6-26B9-08DE039E9AD3', '1918-07-10 21:00:00.0000000', N'SS Umtata, Zanzibar', N'Wednesday July 10th had half day on shore, 3 days holiday for the natives. We had a fine time ashore we saw their fair, also had good look round the town Beer 2/= a pint. Had whisky and sodas at 10'' a drink. More than you get in old England for 2/=. arrived back on board at 10PM perfectly sober.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('14FED862-54DB-4789-26BA-08DE039E9AD3', '1918-07-10 22:00:00.0000000', N'SS Umtata, Zanzibar', N'July 10th to 14th ship took on coal and water. Women working on the coal barges.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D4043A56-2751-4BFF-26BB-08DE039E9AD3', '1918-07-15 05:00:00.0000000', N'SS Umtata, Zanzibar', N'July 15th left Zanzibar at 6AM for ports down the coast first call Lindi', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('13EED214-9251-4DB4-2BEF-08DE04115F16', '1918-07-16 11:15:00.0000000', N'SS Umtata, Lindi', N'July 16th we arrived at Lindi at 12.15PM took black troops on board in the afternoon and almost 120 white troops making 1700 altogether.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B8D96DD6-A830-4EA9-2BF0-08DE04115F16', '1918-07-17 10:45:00.0000000', N'SS Umtata, Mikidani', N'July 17th left Lindi at 8AM passed Mikindani at 11.45AM. Saw 2 Black men flogged on the deck. Made to lay on the deck with their trousers off and receive 10 lashes each with a Kaboko (raw hippo hide)', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('9FB183D5-752D-40FC-2BF1-08DE04115F16', '1918-07-19 06:45:00.0000000', N'SS Umtata, Lumbo', N'July 19th passed Mozambique at 7.15AM, arrived at Lumbo 7.45AM. Disembarked troops and started to unload cargo', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E91DC297-1CE5-49F9-2BF2-08DE04115F16', '1918-07-20 11:00:00.0000000', N'SS Umtata, Lumbo', N'July 20th went ashore in the afternoon walked round the camp and nearly had to stay on shore all night but just managed to get back on board. We had a sing song in the evening on deck. Plenty of Whisky and Cigars.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A1B2C3D4-1111-4AAA-2BF4-08DE04115F16', '1918-07-21 11:00:00.0000000', N'SS Umtata, Lumbo', N'July 21st Chief Steward lost 11 bottles Whisky and £5 in money', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('130DBFD6-C1F5-4BAF-2BF3-08DE04115F16', '1918-07-22 11:00:00.0000000', N'SS Umtata, Lumbo', N'July 22nd Ship baker laid up with bad foot no bread on board. Served out with ships biscuits and they are as hard as bricks', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B2C3D4E5-2222-4BBB-2BF5-08DE04115F16', '1918-07-22 17:30:00.0000000', N'SS Umtata, Lumbo', N'July 22nd at 6.30PM 2nd Officer and Chief Steward fighting about the bread and biscuits. Oh this is a ship.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C3D4E5F6-3333-4CCC-2BF6-08DE04115F16', '1918-07-25 14:30:00.0000000', N'SS Umtata', N'July 25th Finished unloading and left Mozambique B.EA (British East Africa) at 3.30.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D4E5F6A7-4444-4DDD-2BF7-08DE04115F16', '1918-07-26 07:00:00.0000000', N'SS Umtata, Port Amelia (Pemba)', N'July 26th arrived at Port Amelia (Pemba) at 8AM, unloaded by 5PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E5F6A7B8-5555-4EEE-2BF8-08DE04115F16', '1918-07-27 03:30:00.0000000', N'SS Umtata', N'July 27th left Port Amelia at 4.30AM for Lindi. Major gave us great praise at Port Amelia for the way we did our work (what lto)', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F6A7B8C9-6666-4FFF-2BF9-08DE04115F16', '1918-07-28 06:30:00.0000000', N'SS Umtata, Lindi', N'Arrived at Lindi July 28/18 at 7.30AM. Hospital Ship Ubarni came into Lindi at 8AM and left again 4.30PM on July 29th.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A7B8C9D0-7777-4AAA-2BFA-08DE04115F16', '1918-07-29 16:00:00.0000000', N'SS Umtata, Lindi', N'We left Lindi July 29th at 5PM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B8C9D0E1-8888-4BBB-2BFB-08DE04115F16', '1918-07-30 06:00:00.0000000', N'SS Umtata, Kilwa', N'Arrived at Kilwa July 30th at 7AM. Very pretty harbour water edge lined with green trees making it look lovely very small place nothing much doing here Place nearly closed taking up light Railways about 90 miles of it to come up.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C9D0E1F2-9999-4CCC-2BFC-08DE04115F16', '1918-07-31 16:00:00.0000000', N'SS Umtata, Kilwa', N'We left Kilwa July 31st at 5PM for Mozambique P.E.A.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D0E1F2A3-AAAA-4DDD-2BFD-08DE04115F16', '1918-08-02 11:00:00.0000000', N'SS Umtata, Mozambique', N'Arrived at Mozambique at 12 noon on Aug 2nd arrived at Lumbo PM Aug 2nd saw Portugese Cruiser and one English Cruiser the Challenger lying in harbour.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E1F2A3B4-BBBB-4EEE-2BFE-08DE04115F16', '1918-08-03 06:30:00.0000000', N'SS Umtata, Lumbo', N'Hospital Ship Ubani came into Harbour of Lumbo at 7.30AM on Aug 3rd two of the crew of our ship fighting with knives and sticks at 11PM both out and knocked about a great deal had their wounds dressed in the surgery at midnight and again in the morning. This is a ship for fighting and drinking', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F2A3B4C5-CCCC-4FFF-2BFF-08DE04115F16', '1918-08-03 11:00:00.0000000', N'SS Umtata, Lumbo', N'Aug 3rd nothing doing', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A3B4C5D6-DDDD-4AAA-2C00-08DE04115F16', '1918-08-04 11:00:00.0000000', N'SS Umtata, Mozambique', N'Aug 4th Sunday nothing doing but oh Mozambique is a very dear place for anything 3 Rupees for one Bottle Beer 1 Rupee for one Herring eight Pence for a slice of bread so nothing doing in that line for me', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B4C5D6E7-EEEE-4BBB-2C01-08DE04115F16', '1918-08-06 06:30:00.0000000', N'SS Umtata, Lumbo', N'Aug 6th Hospital Ship Gascon came into harbour at 7.30AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C5D6E7F8-FFFF-4CCC-2C02-08DE04115F16', '1918-08-06 11:00:00.0000000', N'SS Umtata, Lumbo', N'Aug 6th nothing doing again', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D6E7F8A9-0000-4DDD-2C03-08DE04115F16', '1918-08-07 11:00:00.0000000', N'SS Umtata, Lumbo', N'Aug 7th nothing doing again but laying about and walking about the deck smoking could do with a little work to help keep me fit have taken to running round the deck of our ship about 12 times first thing in the morning after a good work must do something to keep myself fit', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E7F8A9B0-1111-4EEE-2C04-08DE04115F16', '1918-08-08 11:00:00.0000000', N'SS Umtata, Lumbo', N'Aug 8th went ashore in the morning at Lumbo came back and unloaded 10 cars not bad for 6 days work but at 8PM 2 lights came alongside to be loaded we put 18 cars on them and finished loading them by 10.30 32 more cars left on board', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F8A9B0C1-2222-4FFF-2C05-08DE04115F16', '1918-08-09 11:00:00.0000000', N'SS Umtata, Lumbo', N'Aug 9th very wet morning it has been raining nearly all night and looks like being a very wet day it let off raining about 10.30AM English Cruiser Talbot came into harbour there are now 2 English Cruisers 1 Portuguese Cruiser 2 Hospital ships in harbour Looks very much like business All the troops on shore have Been served out rifles and 100 rounds of ammunition', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A9B0C1D2-3333-4AAA-2C06-08DE04115F16', '1918-08-10 07:00:00.0000000', N'SS Umtata', N'Aug 10th started unloading at 8AM. We left Lumbo at 5PM and left Mozambique at 5.45PM. The sea is very rough old ship rolling about awful I shall be glad when she is loaded again. We took a few Black troops on board at Lumbo for Dar es Sallam.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B0C1D2E3-4444-4BBB-2C07-08DE04115F16', '1918-08-11 12:00:00.0000000', N'SS Umtata, Port Amelia', N'We arrived at Port Amelia aug 11th at 1PM, started to unload at once I went ashore with the mails and two boxes of Butter as escort. Tea time 3rd Engineer and chief steward drunk on board the Skipper signalled to the Cruiser Challenger to send a boat and take them off as prisoners the Challenger sent a squad of marines in Steam Pinnace at 7.30PM and put them both under arrest taking them both on board the challenger', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C1D2E3F4-5555-4CCC-2C08-08DE04115F16', '1918-08-12 11:00:00.0000000', N'SS Umtata, Port Amelia', N'Aug 12th 3rd Engineer to leave our ship at once and the ship steward came back to our ship to clear up his book and accounts and to be put ashore either at Dar es Salaam or Durban. I am on duty today loading motor cars for Dar es Salaam.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D2E3F4A5-6666-4DDD-2C09-08DE04115F16', '1918-08-13 11:00:00.0000000', N'SS Umtata, Port Amelia', N'Aug 13th I am off duty today', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E3F4A5B6-7777-4EEE-2C0A-08DE04115F16', '1918-08-14 11:30:00.0000000', N'SS Umtata', N'Aug 14th on duty this morning. Left Port Amelia at 12.30PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F4A5B6C7-8888-4FFF-2C0B-08DE04115F16', '1918-08-15 05:00:00.0000000', N'SS Umtata, Lindi', N'Aug 15th got up at 6AM, had my usual exercise round the deck we arrived at Lindi at 12.30PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A5B6C7D8-9999-4AAA-2C0C-08DE04115F16', '1918-08-16 16:00:00.0000000', N'SS Umtata, Lindi', N'Aug 16th we left Lindi at 5PM for Dar es Salaam', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B6C7D8E9-AAAA-4BBB-2C0D-08DE04115F16', '1918-08-17 11:00:00.0000000', N'SS Umtata, Dar es Salaam', N'Arrived outside DSM Harbour at 12 noon and dropped anchor in harbour at 12:45 on Aug 17th. Did nothing the remainder of day.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C7D8E9F0-BBBB-4CCC-2C0E-08DE04115F16', '1918-08-18 11:00:00.0000000', N'Dar es Salaam', N'Aug 18th Sunday started unloading I went to Post Office and our camp for letters. I received 3 letters and 1 paper. 2 lovely photos of ma May and Bertie. Went on duty after lunch.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D8E9F0A1-CCCC-4DDD-2C0F-08DE04115F16', '1918-08-19 11:00:00.0000000', N'Dar es Salaam', N'Aug 19th finished unloading after working all night', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E9F0A1B2-DDDD-4EEE-2C10-08DE04115F16', '1918-08-20 07:00:00.0000000', N'SS Umtata, Zanzibar', N'Aug 20th we left DSM at 8AM and arrived at Zanzibar at 12 noon same day for coal and water. Two English Cruisers laying in harbour here.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F0A1B2C3-EEEE-4FFF-2C11-08DE04115F16', '1918-08-21 11:00:00.0000000', N'Zanzibar', N'Aug 21st we have some white boys aboard so we gave them some of our lunch as they were running short of rations. We went aboard the Salamus in the afternoon with the other boys who are working on her and we had some beer. Our Corporal had two of his chums from the Salamus on board our ship to dinner, damn swank, and ordered us to the other end of the ship after dinner out of their way but of course we did not move so they went themselves. We are expecting some trouble in the morning from them.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B2C3D4E5-0000-4BBB-2C13-08DE04115F16', '1918-08-22 12:45:00.0000000', N'SS Umtata', N'Aug 22nd no trouble yet. We left Zanzibar at 1.45PM for Kilwa', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C3D4E5F6-1111-4CCC-2C14-08DE04115F16', '1918-08-24 10:15:00.0000000', N'SS Umtata, Kilwa', N'Arrived at Kilwa at 11.15AM on Saturday Aug 24th and started to unload at once', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D4E5F6A7-2222-4DDD-2C15-08DE04115F16', '1918-08-25 11:00:00.0000000', N'SS Umtata, Kilwa', N'Aug 25th loading up motor cars and all kinds of carts. Working hard all day. Not much fishing as the water is too deep. Let off work at 5PM, no stevedores here we have to do it all ourselves', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E5F6A7B8-3333-4EEE-2C16-08DE04115F16', '1918-08-26 11:00:00.0000000', N'SS Umtata, Kilwa', N'Aug 26th working hard all day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F6A7B8C9-4444-4FFF-2C17-08DE04115F16', '1918-08-27 11:00:00.0000000', N'SS Umtata, Kilwa', N'Aug 27th working hard all day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A7B8C9D0-5555-4AAA-2C18-08DE04115F16', '1918-08-28 11:00:00.0000000', N'SS Umtata, Kilwa', N'Aug 28th working hard all day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B8C9D0E1-6666-4BBB-2C19-08DE04115F16', '1918-08-28 19:00:00.0000000', N'SS Umtata, Kilwa', N'Aug 28th Captain had some friends from shore for the evening we were invited also and we had a good evening. Plenty of whisky and beer and cigars. Two of my pals got fighting afterwards but it all ended alright.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C9D0E1F2-7777-4CCC-2C1A-08DE04115F16', '1918-08-29 05:00:00.0000000', N'SS Umtata, Kilwa', N'Aug 29th all ready for work at 6AM but no steam. It is Raining in torrents. We got no steam until 7AM. We finished loading at lunch time and left Kilwa at 4PM for DSM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D0E1F2A3-8888-4DDD-2C1B-08DE04115F16', '1918-08-30 06:30:00.0000000', N'SS Umtata, Dar es Salaam', N'Arrived outside DSM harbour at 7.30AM on Aug 30th. Entered the harbour and dropped anchor at 10.30AM. Rain in torrents', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E1F2A3B4-9999-4EEE-2C1C-08DE04115F16', '1918-08-31 11:00:00.0000000', N'Dar es Salaam', N'Saturday Aug 31st unloading all day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F2A3B4C5-AAAA-4FFF-2C1D-08DE04115F16', '1918-09-01 11:00:00.0000000', N'Dar es Salaam', N'Sunday Sept 1st I went ashore for letters but got none for any of the boys I went to our Camp for some clothes for the boys I got 1 pair of trousers and one tunic shirt and 1 hair brush for myself. We started loading up cargo at 7PM. I am off duty tonight.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A3B4C5D6-BBBB-4AAA-2C1E-08DE04115F16', '1918-09-02 11:00:00.0000000', N'Dar es Salaam', N'Sept 2nd on duty today. Worked till 5PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B4C5D6E7-CCCC-4BBB-2C1F-08DE04115F16', '1918-09-02 18:00:00.0000000', N'Dar es Salaam', N'Sept 2nd 2 Black Boys captured in ships store room eating jam and bully beef. 2nd Steward and one of our boys to go ashore in the morning as witnesses against them poor boys', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C5D6E7F8-DDDD-4CCC-2C20-08DE04115F16', '1918-09-03 06:00:00.0000000', N'Dar es Salaam', N'Sept 3rd on duty at 7AM. Working all day not allowed ashore. Going to see the MLO in the morning', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D6E7F8A9-EEEE-4DDD-2C21-08DE04115F16', '1918-09-04 11:00:00.0000000', N'Dar es Salaam', N'Sept 4th finished loading in the afternoon I went ashore in the evening. Had dinner at the hotel as guest of our stevedores. I went to the Pictures after dinner. I had a good time on shore. SS Trent laying outside harbour. Sorry she did not come in.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E7F8A9B0-FFFF-4EEE-2C22-08DE04115F16', '1918-09-05 14:30:00.0000000', N'SS Umtata', N'Sept 5th left DSM at 3.30', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F8A9B0C1-0000-4FFF-2C23-08DE04115F16', '1918-09-06 09:30:00.0000000', N'SS Umtata, Kilwa', N'Arrived at Kilwa Sept 6th at 10.30AM and left again same day at 5.30. I went ashore this afternoon to play in a cricket match. We lost.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A9B0C1D2-1111-4AAA-2C24-08DE04115F16', '1918-09-07 07:30:00.0000000', N'SS Umtata, Lindi', N'Sept 7th arrived at Lindi about 8.30AM. Started work about 10AM finished unloading.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B0C1D2E3-2222-4BBB-2C25-08DE04115F16', '1918-09-08 15:00:00.0000000', N'SS Umtata', N'Sunday morning left Lindi for Port Amelia Sept 8th at 4PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C1D2E3F4-3333-4CCC-2C26-08DE04115F16', '1918-09-09 17:00:00.0000000', N'SS Umtata, Port Amelia', N'Arrived at Pt Amelia Sept 9th about 6PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D2E3F4A5-4444-4DDD-2C27-08DE04115F16', '1918-09-10 11:00:00.0000000', N'SS Umtata, Port Amelia', N'Sept 10th Started unloading', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E3F4A5B6-5555-4EEE-2C28-08DE04115F16', '1918-09-11 11:00:00.0000000', N'Port Amelia', N'Sept 11th something wrong in the engine room had to stop all work so we cleaned up and went ashore and got permission to go through the native village. It was the sight of a lifetime. One could easily write a book about all we saw.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F4A5B6C7-6666-4FFF-2C29-08DE04115F16', '1918-09-12 11:00:00.0000000', N'SS Umtata, Port Amelia', N'Sept 12th working all day. Feeling a bit done up tonight, shall turn in early.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A5B6C7D8-7777-4AAA-2C2A-08DE04115F16', '1918-09-13 11:00:00.0000000', N'SS Umtata, Port Amelia', N'Sept 13th feeling better this morning working all day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B6C7D8E9-8888-4BBB-2C2B-08DE04115F16', '1918-09-14 15:00:00.0000000', N'SS Umtata', N'Sept 14th finished loading and left Port Ameilia at 4PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C7D8E9F0-9999-4CCC-2C2C-08DE04115F16', '1918-09-15 06:00:00.0000000', N'SS Umtata, Lumbo', N'Sept 15th arrived at Mozambique at 7AM arrived at Lumbo at 7.45AM. Hospital ship Gascon in harbour.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D8E9F0A1-AAAA-4DDD-2C2D-08DE04115F16', '1918-09-16 11:00:00.0000000', N'SS Umtata, Lumbo', N'Sept 16th finished unloading & loaded up again, took on 500 Black Troopers and a lot of White troopers. In the afternoon we had a very nice little evening us five boys the Bert and most sociable time we have been aboard. I mention this because two of us five are Yankees one is alright. The other I am sorry to say we had to tame him as he would get a few glasses of whisky and start a row. One night he started on me. Now he is more tame. Last night was the best he has been after a drink.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E9F0A1B2-BBBB-4EEE-2C2E-08DE04115F16', '1918-09-17 07:00:00.0000000', N'SS Umtata', N'Sept 17th left Lumbo at 8AM. Some engine trouble at sea at 10.30AM we hove to for an hour. The old ship did roll. You would think she was going to turn over', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F0A1B2C3-CCCC-4FFF-2C2F-08DE04115F16', '1918-09-18 11:00:00.0000000', N'SS Umtata', N'Sept 18th Quiet day at sea. I never saw the ocean so calm and oily looking. Looks as if we are in for a bad storm', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A1B2C3D4-DDDD-4AAA-2C30-08DE04115F16', '1918-09-19 11:00:00.0000000', N'SS Umtata', N'Sept 19th yesterday and last night passed without getting the expected storm the sea is more natural this morning.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B2C3D4E5-EEEE-4BBB-2C31-08DE04115F16', '1918-09-20 06:00:00.0000000', N'SS Umtata, Kilwa', N'Arrived a Kilwa sept 20/18 at 7AM. Started to load first thing after breakfast. We had a mishap in the afternoon 3 pontoons lashed together with heavy boilers & machinery on them. When we lifted the first boiler all the others collapsed the centre one sinking under water, but we only lost one engine, but it was very exciting while it lasted. It was time to see the black boys dive under the water to fasten ropes on the Boiler & boxes of machinery.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C3D4E5F6-FFFF-4CCC-2C32-08DE04115F16', '1918-09-21 11:00:00.0000000', N'SS Umtata, Kilwa', N'Sept 21st Working all day. The officer working with me has his thumb nail torn right clean off. I feel sorry for him as he is a damn nice fellow. We are now filling up with Black & White Troopers. You can hardly move on deck for them. Got the wind up today thinking about Poor Mays birthday. I wish I was home with you all.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D4E5F6A7-0000-4DDD-2C33-08DE04115F16', '1918-09-22 10:00:00.0000000', N'SS Umtata', N'Sunday Sept 22nd finished loading at 11AM and left Kilwa Kiswani at 2.30PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E5F6A7B8-1111-4EEE-2C34-08DE04115F16', '1918-09-23 06:30:00.0000000', N'SS Umtata, Dar es Salaam', N'Monday Sept 23rd arrived outside D.S.M. at 7.30AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F6A7B8C9-2222-4FFF-2C35-08DE04115F16', '1918-09-24 07:45:00.0000000', N'Dar es Salaam', N'Tuesday Sept 24th new draft arrived from England and landed at 8.45AM. Left SS Umtata for Camp at 4.45PM. Walked to the camp had tea and went in the town in the evening. We shall miss the food on the Old Umtata.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A7B8C9D0-3333-4AAA-2C36-08DE04115F16', '1918-09-25 04:30:00.0000000', N'Dar es Salaam', N'Wednesday Sept 25th up at 5.30. Breakfast at 6AM bully beef and bread. Very different to a 6 course Breakfast but there it is we must make the best of it. Saw the major at 7AM he says you Boys are to go aboard the Hang today. We were pleased. Later order fall in at orderly room at 1.30 to go aboard the Hung shows at 2PM. Packed up in quick time got aboard about 3PM. Very much different from the Umtata but I think we can make ourselves very comfy. I hope we shall stay on this ship until the old Umtata comes back but this one will do us for the duration. No 6 or 7 course meals and then go away hungry. If we are treated all the time we are on this ship as we have been for the few hours we have been aboard her why we shall be alright. She has a mixed crew, Indians and Chinese but mostly Chinese. No work today shall start tomorrow', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B8C9D0E1-4444-4BBB-2C37-08DE04115F16', '1918-09-26 11:00:00.0000000', N'SS Hang Moh, Dar es Salaam', N'Thursday Sept 26th started work at 12 noon at no4 hatch. Finished at 5PM. Our cabins are much more roomy and cooler on this ship.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C9D0E1F2-5555-4CCC-2C38-08DE04115F16', '1918-09-27 11:00:00.0000000', N'SS Hang Moh, Dar es Salaam', N'Friday Sept 27th finished loading. Went ashore for mails got letters for all the boys but none for myself. I received 4 papers. We had a good evening before we left I went aboard the Salaaraws', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D0E1F2A3-6666-4DDD-2C39-08DE04115F16', '1918-09-28 10:00:00.0000000', N'SS Hang Moh', N'Sept 28th we left D.S.M about 11AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E1F2A3B4-7777-4EEE-2C3A-08DE04115F16', '1918-09-29 04:30:00.0000000', N'SS Hang Moh, Kilindini', N'Arrived outside Kilindini about 5.30AM Sept 29/18. Started unloading after breakfast', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F2A3B4C5-8888-4FFF-2C3B-08DE04115F16', '1918-09-30 12:30:00.0000000', N'SS Hang Moh', N'Sept 30th left Kilindini at 1.30PM we are a lot more comfortable on this ship as we have more room in our cabins and they are away from the Engines and Boilers. In the Umtata we were sleeping right on the top of the Boilers and our cabin was like a Turkish Bath', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A3B4C5D6-9999-4AAA-2C3C-08DE04115F16', '1918-10-02 16:30:00.0000000', N'SS Hang Moh, Port Amelia', N'Oct 2nd we arrived at Port Amelia at 5:30PM after a very nice voyage', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B4C5D6E7-AAAA-4BBB-2C3D-08DE04115F16', '1918-10-03 09:30:00.0000000', N'SS Hang Moh', N'Oct 3rd we took a big load of Black Troops aboard and left Port Amelia about 10:30AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C5D6E7F8-BBBB-4CCC-2C3E-08DE04115F16', '1918-10-05 05:00:00.0000000', N'SS Hang Moh, Dar es Salaam', N'After a smooth run we reached D.S.M on Oct 5th in the morning about 6AM after running on reduced speed all night. The tug starts come out of harbour for the troops I think we are waiting for the tide before we can go in. Went in harbour about 5PM. Disembarked troops and took on mails for transhipment at Zanzibar', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D6E7F8A9-CCCC-4DDD-2C3F-08DE04115F16', '1918-10-06 15:30:00.0000000', N'SS Hang Moh', N'Oct 6th left D.S.M at 4.30PM and arrived outside Zanzibar about 8PM anchored for the night.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E7F8A9B0-DDDD-4EEE-2C40-08DE04115F16', '1918-10-07 05:00:00.0000000', N'SS Hang Moh, Zanzibar', N'Reached Zanzibar at 6AM on Oct 7th for coal and water. Nothing doing only read & smoke', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F8A9B0C1-EEEE-4FFF-2C41-08DE04115F16', '1918-10-09 11:00:00.0000000', N'SS Hang Moh, Zanzibar', N'Oct 9th nothing doing. Getting fed up with nothing to do. Have not done one stroke of work since a week ago last Friday. Don''t want too much work but would like a little occupy ones mind a little bit. Work keeps me from thinking about thing that get the wind up one', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A9B0C1D2-FFFF-4AAA-2C42-08DE04115F16', '1918-10-10 03:30:00.0000000', N'SS Hang Moh', N'Oct 10th Left Zanzibar about 4.30AM for Port Amelia', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B0C1D2E3-0000-4BBB-2C43-08DE04115F16', '1918-10-11 07:30:00.0000000', N'SS Hang Moh', N'Oct 11th overslept. Woke up at 8.30AM instead of 6.30AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C1D2E3F4-1111-4CCC-2C44-08DE04115F16', '1918-10-11 17:30:00.0000000', N'SS Hang Moh, Port Amelia', N'Oct 11th arrived at Port Amelia at 6.30PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D2E3F4A5-2222-4DDD-2C45-08DE04115F16', '1918-10-12 11:00:00.0000000', N'SS Hang Moh', N'Oct 12th started to load on motor cars and left for DSM about 7PM. The Ingoma left at 5.30 we caught her up and passed her next day.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E3F4A5B6-3333-4EEE-2C46-08DE04115F16', '1918-10-14 05:00:00.0000000', N'SS Hang Moh, Dar es Salaam', N'We arrived outside Daressalaam at 6AM one hour before the Ingoma on Monday 14th Oct', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F4A5B6C7-4444-4FFF-2C47-08DE04115F16', '1918-10-15 11:00:00.0000000', N'Dar es Salaam', N'Tuesday Oct 15th nothing doing', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A5B6C7D8-5555-4AAA-2C48-08DE04115F16', '1918-10-16 11:00:00.0000000', N'Dar es Salaam', N'Wednesday Oct 16th went ashore for mails and our pay. I received 2 Papers but no letter. Got a money order for £1 to send home.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B6C7D8E9-6666-4BBB-2C49-08DE04115F16', '1918-10-17 11:00:00.0000000', N'Dar es Salaam', N'Thursday Oct 17th I went ashore by myself to send the money and a letter home. The harbour is full of troop ships. We are bringing thousands upon thousands of Black Troops up from the down the coast to Daressalaam as the German Army, which is composed mostly of Black Troops, is in German East Africa again. Our army has followed him from British E.A and through German E.A and through Portuguese E.A nearly into Rhodesia and now back again into German E.A. Hundreds & hundreds of miles', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C7D8E9F0-7777-4CCC-2C4A-08DE04115F16', '1918-10-17 12:30:00.0000000', N'SS Hang Moh', N'Thursday Oct 17th we left Daressalaam for Lindi at 1.30PM. We have done no work this time in Port in fact we have not done 3 days work all told since we came on this ship as we keep going from Port to Port for troops and not waiting for Cargo. I am getting the wind up properly. Getting no letters from home it worries me a great deal.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D8E9F0A1-8888-4DDD-2C4B-08DE04115F16', '1918-10-18 10:30:00.0000000', N'SS Hang Moh, Lindi', N'We arrived at Lindi about 11.30AM Oct 18th took on motor cars and Black Troops. Finished loading and got steam up already for leaving Sunday afternoon Oct 20th but got orders to stay all night to take more troops on in the morn', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E9F0A1B2-9999-4EEE-2C4C-08DE04115F16', '1918-10-21 12:00:00.0000000', N'SS Hang Moh', N'Left for Daresalaam Oct 21st at 1PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F0A1B2C3-AAAA-4FFF-2C4D-08DE04115F16', '1918-10-22 05:30:00.0000000', N'SS Hang Moh, Dar es Salaam', N'Arrived outside D.S.M at 6.30AM on Oct 22nd. Went into the harbour at 5PM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A1B2C3D4-BBBB-4AAA-2C4E-08DE04115F16', '1918-10-23 11:00:00.0000000', N'Dar es Salaam', N'Oct 23rd nothing doing all day', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B2C3D4E5-CCCC-4BBB-2C4F-08DE04115F16', '1918-10-24 11:00:00.0000000', N'Dar es Salaam', N'Oct 24th nothing doing. Me and my Pal went ashore in the afternoon. Met the civilian Stevedores. They are finished work here (WT or IWT) doing it. All these Stevedores were going back to Durban but when they got to the Quay with all their boxes and things they were not allowed to land or leave. Durban as the Spanish Fever. Is so bad hundreds are dying with it so, these Boys just had the wind up nicely they got their Boss to sign a paper for a case of Whisky. We went to their hotel with them and we had some. We stayed for dinner with them and we had a great old time. Felt query next morning', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C3D4E5F6-DDDD-4CCC-2C50-08DE04115F16', '1918-10-25 11:00:00.0000000', N'Dar es Salaam', N'Oct 25th nothing doing again', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D4E5F6A7-EEEE-4DDD-2C51-08DE04115F16', '1918-10-26 08:00:00.0000000', N'SS Hang Moh', N'Oct 26th left Daresalaam at 9AM for Mozambique. We have a German Prisoner in the second class cabin with us. He seems a very descent sort of fellow but I have not time for any B. Germans, We had a rough passage this time down.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E5F6A7B8-FFFF-4EEE-2C52-08DE04115F16', '1918-10-28 10:30:00.0000000', N'SS Hang Moh, Mozambique', N'We arrived at Mozambique Oct 28th about 11.30AM', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F6A7B8C9-0000-4FFF-2C53-08DE04115F16', '1918-10-29 11:00:00.0000000', N'SS Hang Moh, Mozambique', N'Oct 29th started to load up. We took on a big load over 100 motor cars and about 15000 bags of sores besides several hundred tones of Hospital stores and utensils.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A7B8C9D0-1111-4AAA-2C54-08DE04115F16', '1918-11-02 11:00:00.0000000', N'SS Hang Moh', N'We finished loading on Saturday noon Nov 2nd and left for Daresalaam at 3.30PM with White and Black troops on board. We had news that Turkey had given in before we left which cheered us up and we had a small wet up on that. My mate and our Corporal had a bit of a fight at the finish but nothing in it. I would sooner have a drink.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B8C9D0E1-2222-4BBB-2C55-08DE04115F16', '1918-11-04 17:00:00.0000000', N'SS Hang Moh, Dar es Salaam', N'We arrived outside Daresalaam on Nov 4th at 6PM.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C9D0E1F2-3333-4CCC-2C56-08DE04115F16', '1918-11-05 11:00:00.0000000', N'Dar es Salaam', N'We stayed out until 4PM on Nov 5th before we went into harbour going ashore in the morning for letters. We heard today that Austria had given in. What now then Germany lets have you.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D0E1F2A3-4444-4DDD-2C57-08DE04115F16', '1918-11-07 11:00:00.0000000', N'Dar es Salaam', N'Nov 7th we had a few hours notice to pack up and leave the hang moh got the wind up all the men are taken off the ships as each ship comes into harbour. We have to report ourselves tomorrow morning for work ashore.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E1F2A3B4-5555-4EEE-2C58-08DE04115F16', '1918-11-08 07:30:00.0000000', N'Dar es Salaam', N'At MLO Office at 8.30 this morning for work & was sent back to Camp I am to go on tonight at 6PM until 12', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F2A3B4C5-6666-4FFF-2C59-08DE04115F16', '1918-11-09 11:00:00.0000000', N'Dar es Salaam', N'Nov 9th no work all day. Concert in the evening at YMCA', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A3B4C5D6-7777-4AAA-2C5A-08DE04115F16', '1918-11-10 05:00:00.0000000', N'Dar es Salaam', N'Change of shift today Nov 10th Sunday started work at 6AM until 12 Camp time of it. Heard today that the Kaiser has given up his throne', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B4C5D6E7-8888-4BBB-2C5B-08DE04115F16', '1918-11-11 05:00:00.0000000', N'Dar es Salaam', N'Nov 11th should work at 6AM left off at 12 midday. Went to a Concert in the evening it was a nice change after being aboard ship so long the food is not so much or as good as it was on the ship but I think I can stick it. Alright we had news today that the armistice was signed at 5AM. The order given in all the camps here that there was to be no demonstration of any kin. A bit off as our col had made arrangements for a bit of a set to but nothing doing but thank God it is over. Now for Blighty', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C5D6E7F8-9999-4CCC-2C5C-08DE04115F16', '1918-11-12 05:00:00.0000000', N'Dar es Salaam', N'Nov 12th started work at 6AM nothing doing left off again at 7AM. I had to toss my mate to see which of us should go. I won so I had the day off', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D6E7F8A9-AAAA-4DDD-2C5D-08DE04115F16', '1918-11-14 11:00:00.0000000', N'Dar es Salaam', N'Nov 14th no work again today but it is my turn to stay here until 12 to see the Sheder don''t run away', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E7F8A9B0-BBBB-4EEE-2C5E-08DE04115F16', '1918-11-15 05:00:00.0000000', N'Dar es Salaam', N'Nov 15th Started work at 6AM. It is raining very hard now but we managed to get to work in the dry before it started. It has been raining all day. Just heard German General Von Lets surrendered yesterday', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F8A9B0C1-CCCC-4FFF-2C5F-08DE04115F16', '1918-11-14 12:00:00.0000000', N'Dar es Salaam', N'Nov 14th The War is over in East Africa now Thank God. Extra half hour for lights to be on tonight because the fighting is over.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('A9B0C1D2-DDDD-4AAA-2C60-08DE04115F16', '1918-11-16 03:30:00.0000000', N'Dar es Salaam', N'Nov 16th started work a 6AM got up as usual at 4.30 Breakfast at 5AM Bully Beef dry Bread. Bread and jam for dinner at 11AM. Left off work at 12 midday got my hair cur cost 75 cent 1/=. Not bad is it but you can''t get it done for less out here', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('B0C1D2E3-EEEE-4BBB-2C61-08DE04115F16', '1919-02-16 11:00:00.0000000', N'Dar es Salaam', N'I left Daresalaam East Africa for good old Blighty on Sunday Feb 16th 1919.', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('C1D2E3F4-FFFF-4CCC-2C62-08DE04115F16', '1919-02-23 11:00:00.0000000', N'Durban', N'I arrived at Durban on Sunday Feb 23rd on my birthday. Durban is a very nice place but all the Pubs were closed to soldiers but I went up to the Camp to the Canteen to get just one as it was my Birthday. Had more than one but not too many I sent some letter cards home from Durban', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('D2E3F4A5-0000-4DDD-2C63-08DE04115F16', '1919-02-24 11:00:00.0000000', N'Durban', N'We all left Durban on Feb 24th', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('E3F4A5B6-1111-4EEE-2C64-08DE04115F16', '1919-03-01 11:00:00.0000000', N'Cape Town', N'Arrived at Cape Town on Friday March 1st and sent to a rest Camp at Wynberg it was very nice to be amongst white people again. All the pubs in Wynberg and Cape Town are open to Imperial Troops but not to Colonials. We had a good time here for four or five days', '61625950-9C26-46EF-1B98-08DD14BC2509'),
    ('F4A5B6C7-2222-4FFF-2C65-08DE04115F16', '1919-03-05 11:00:00.0000000', N'Cape Town', N'We left Cape Town for good old Southampton on March 5th which place we hope to reach by March 25th', '61625950-9C26-46EF-1B98-08DD14BC2509')
) AS source (DiaryEntryId, Date, Location, Entry, DiaryId)
ON target.DiaryEntryId = source.DiaryEntryId
WHEN MATCHED THEN UPDATE SET Date = source.Date, Location = source.Location, Entry = source.Entry, DiaryId = source.DiaryId
WHEN NOT MATCHED THEN INSERT (DiaryEntryId, Date, Location, Entry, DiaryId) VALUES (source.DiaryEntryId, source.Date, source.Location, source.Entry, source.DiaryId);
